// Every unit derives from this. Finished: use it as it is.
abstract class Unit
{
    public string Name { get; }
    public int Health { get; protected set; }
    public bool IsAlive => Health > 0;

    protected Unit(string name, int health)
    {
        Name = name;
        Health = health;
    }

    // Lose the full damage, but never below 0.
    public virtual void TakeDamage(int amount)
    {
        Health = Math.Max(0, Health - amount);
    }

    public abstract int AttackPower();

    public override string ToString() => $"{Name} ({Health} HP)";
}

// A finished unit, to show the pattern.
class Archer : Unit
{
    public Archer(string name) : base(name, 60) { }

    public override int AttackPower() => 12;
}

// A Knight starts with 100 health and hits for 15.
// Armour: every hit does 5 less damage, but always at least 1.
class Knight : Unit
{
    public Knight(string name)
    {
    }

    public override int AttackPower() => 15;

    public void TakeDamage(int amount)
    {
        int reduced = amount - 5;
        Health = Health - reduced;
    }
}

