class FreeOver : IShippingRate
{
    private readonly decimal _threshold;
    private readonly IShippingRate _inner;

    public FreeOver(decimal threshold, IShippingRate inner)
    {
        _threshold = threshold;
        _inner = inner;
    }

    public string Name => $"{_inner.Name}, free over {_threshold:F2}";

    public decimal Cost(Parcel parcel)
        => parcel.Value >= _threshold ? 0m : _inner.Cost(parcel);
}

static class Checkout
{
    // TODO: return the rate with the lowest cost for this parcel.
    public static IShippingRate Cheapest(
        Parcel parcel, IEnumerable<IShippingRate> rates)
    {
        if (!rates.Any())
            throw new ArgumentException("There are no rates to choose from.");
        return rates.MinBy(rate => rate.Cost(parcel));
    }
}

