// One sale: units of a product sold in a region, at a price per unit.
record Sale(string Region, string Product, int Units, decimal Price)
{
    public decimal Total => Units * Price;
}

static class SalesReport
{
    // 1. The names of the products with the most revenue (all their sales
    //    added up), highest first, ties by name, at most count of them.
    public static List<string> TopProducts(IEnumerable<Sale> sales, int count)
    {
        return sales
            .GroupBy(s => s.Product)
            .Select(g => new { Product = g.Key, Revenue = g.Sum(s => s.Total) })
            .OrderByDescending(p => p.Revenue)
            .ThenBy(p => p.Product)
            .Take(count)
            .Select(p => p.Product)
            .ToList();
    }

    // 2. Total revenue for each region.
    public static Dictionary<string, decimal> RevenueByRegion(IEnumerable<Sale> sales)
    {
        return sales
            .GroupBy(s => s.Region)
            .ToDictionary(g => g.Key, g => g.Sum(s => s.Total));
    }

    // 3. The region with the most revenue, or null when there are no sales.
    public static string BestRegion(IEnumerable<Sale> sales)
    {
        return RevenueByRegion(sales)
            .OrderByDescending(pair => pair.Value)
            .Select(pair => pair.Key)
            .FirstOrDefault();
    }

    // 4. The sales of 10 units or more, as a snapshot: sales added to the
    //    list later must not show up in it.
    public static IEnumerable<Sale> LargeOrders(List<Sale> sales)
    {
        return sales.Where(s => s.Units >= 10).ToList();
    }
}

